# test_normalizer.py
import unittest

def normalize(record):
    return {**record, "host": record["host"].lower(), "state": record["state"].lower()}

class NormalizerTests(unittest.TestCase):
    def test_normalized_fields(self):
        original = {"id": " F1-A ", "host": "Lab-ONE", "state": "CONFIRMED"}
        self.assertEqual(normalize(original), {"id": " F1-A ", "host": "lab-one", "state": "confirmed"})
        self.assertEqual(original["host"], "Lab-ONE")

# Linux/macOS: python3 -m unittest -v test_normalizer
# Windows: py -3 -m unittest -v test_normalizer
